export type NoteType = 'text' | 'link' | 'file' | 'image' | 'code' | 'embed'

export type Note = {
  id: string
  authorId: string
  parentId: string
  parentType: 'objective' | 'task' | 'project'
  type: NoteType
  content: string
  metadata?: Record<string, unknown>
  createdAt: string
  updatedAt: string
}
